UPDATE speed_leads
SET qualifying_answers = $1, status = 'qualified'
WHERE external_id = $2;

parameters.jsCode:
// Pull the qualifying answers and external_id from earlier nodes,
// since this node's immediate input only has {"success": true}
const answers = $('Set - Parse Extracted Answers').item.json.qualifying_answers;
const externalId = $('Postgres - Look Up Awaiting Lead').item.json.external_id;

let score = 0;
const reasons = [];

// --- Need (max 25 points) ---
// A stated need earns points just for existing; a vague "just curious"
// type answer still counts as present, since we're not judging quality here.
if (answers.need && answers.need.trim().length > 0) {
  score += 25;
  reasons.push('need stated (+25)');
}

// --- Timeline (max 30 points) ---
// Keyword-based scoring: sooner language scores higher.
// Checked in order from most urgent to least, first match wins.
const timelineText = (answers.timeline || '').toLowerCase();
if (/week|asap|immediately|urgent/.test(timelineText)) {
  score += 30;
  reasons.push('urgent timeline (+30)');
} else if (/month/.test(timelineText)) {
  score += 20;
  reasons.push('this-month timeline (+20)');
} else if (/quarter/.test(timelineText)) {
  score += 10;
  reasons.push('this-quarter timeline (+10)');
} else if (/explor|just looking|not sure/.test(timelineText)) {
  score += 0;
  reasons.push('exploratory timeline (+0)');
} else if (timelineText.trim().length > 0) {
  // Said something, but it didn't match a known pattern —
  // give partial credit rather than zero, since they did engage.
  score += 5;
  reasons.push('unclassified timeline (+5)');
}

// --- Budget (max 30 points) ---
// Extract the first number mentioned (handles "$1600", "1,600", "around 500").
const budgetText = answers.budget || '';
const budgetMatch = budgetText.replace(/,/g, '').match(/\d+/);
if (budgetMatch) {
  const amount = parseInt(budgetMatch[0], 10);
  if (amount >= 1000) {
    score += 30;
    reasons.push(`budget ${amount} >= 1000 (+30)`);
  } else if (amount >= 300) {
    score += 15;
    reasons.push(`budget ${amount} >= 300 (+15)`);
  } else {
    score += 5;
    reasons.push(`budget ${amount} stated but low (+5)`);
  }
} else if (budgetText.trim().length > 0) {
  // They said something ("not sure yet", "flexible") but no number given.
  score += 5;
  reasons.push('budget mentioned, no number (+5)');
}

// --- Authority (max 15 points) ---
const authorityText = (answers.authority || '').toLowerCase();
if (/yes|i am|i'm the one|final call|my decision/.test(authorityText)) {
  score += 15;
  reasons.push('confirmed decision-maker (+15)');
} else if (/no|others|team|involve/.test(authorityText)) {
  score += 0;
  reasons.push('not sole decision-maker (+0)');
}

return [{
  json: {
    external_id: externalId,
    score,
    score_reasons: reasons // useful for debugging/auditing why a lead scored the way it did
  }
}];

